def bit_stuff(data):
    stuffed = ''
    count = 0
    for bit in data:
        stuffed += bit
        if bit == '1':
            count += 1
            if count == 5:
                stuffed += '0'  # insert 0 after five 1s
                count = 0
        else:
            count = 0
    return stuffed

