def verify_checksum(data_words, sent_checksum):
    total_sum = sum(data_words)
    while (total_sum >> 16):
        total_sum = (total_sum & 0xFFFF) + (total_sum >> 16)
    calculated_checksum = ~total_sum & 0xFFFF
    return calculated_checksum == sent_checksum

def mod2div(dividend, divisor):
    pick = len(divisor)
    temp = dividend[:pick]
    while pick < len(dividend):
        if temp[0] == '1':
            temp = ''.join([str(int(a) ^ int(b)) for a, b in zip(temp, divisor)])[1:] + dividend[pick]
        else:
            temp = temp[1:] + dividend[pick]
        pick += 1
    if temp[0] == '1':
        temp = ''.join([str(int(a) ^ int(b)) for a, b in zip(temp, divisor)])[1:]
    else:
        temp = temp[1:]
    return temp

