class GoBackNSender:
    def __init__(self, window_size, total_seq):
        self.N = window_size
        self.max_seq = total_seq
        self.base = 0
        self.next_seq_num = 0

    def send_frame(self):
        if self.next_seq_num < self.base + self.N and self.next_seq_num < self.max_seq:
            print(f'Sending Frame {self.next_seq_num}')
            self.next_seq_num += 1
        else:
            print('Window is full. Cannot send.')

    def receive_ack(self, ack_num):
        if ack_num >= self.base:
            print(f'Cumulative ACK {ack_num} received. Sliding window.')
            self.base = ack_num + 1

