def select_best_bgp_route(route1, route2):
    # route tuple format: (route_id, local_pref, as_path_length)
    if route1[1] != route2[1]:
        return route1[0] if route1[1] > route2[1] else route2[0]

    if route1[2] != route2[2]:
        return route1[0] if route1[2] < route2[2] else route2[0]

    return route1[0] # Default tie-breaker

